import itertools

n = 13
fixed = {8: 1, 10: -1}

def compute_C(seq, k):
    total = 0
    for i in range(n - k):
        total += seq[i] * seq[i+k]
    return total

def is_valid(seq):
    # check fixed positions
    for idx, val in fixed.items():
        if seq[idx] != val:
            return False
    # check C4 and C5
    if compute_C(seq, 4) != 2:
        return False
    if compute_C(seq, 5) != -1:
        return False
    # compute sum of squares
    total_sq = 0
    for k in range(1, n):
        ck = compute_C(seq, k)
        total_sq += ck * ck
    if total_sq <= 28:
        return True
    return False

# brute force
solutions = []
for bits in itertools.product([-1, 1], repeat=n):
    seq = list(bits)
    if is_valid(seq):
        solutions.append(seq)
        print("Found:", seq)
        break

if not solutions:
    print("No solution found")
else:
    seq = solutions[0]
    print("Sequence:", seq)
    # print C_k
    for k in range(1, n):
        print(f"C_{k} = {compute_C(seq, k)}")
    total = sum(compute_C(seq, k)**2 for k in range(1, n))
    print("Sum squares:", total)

